         'svc.cosmetic-dentistry.intro': 'يشمل طب الأسنان التجميلي العلاجات التي تغيّر مظهر أسنانك: لونها وشكلها وطريقة اصطفافها عندما تبتسم. معظم ما نقوم به هنا سريع، ويمكن إنجاز عدة علاجات في زيارة واحدة.',
         'svc.cosmetic-dentistry.involves': 'نبدأ بالاستماع إلى ما تريد تغييره، ثم نتأكد من أن الأسنان سليمة، فلا فائدة من وضع قشرة فوق سن مسوّس. يزيل التبييض البقع الناتجة عن القهوة والشاي والتدخين. والقشور (الفينير) طبقات رقيقة تُلصق على واجهة السن لتصحيح شكله أو لونه. أما التيجان فتعيد بناء السن المتآكل أو المكسور بشدة، وإعادة التشكيل تنعّم الكسور الصغيرة والحواف غير المستوية.',
         'svc.cosmetic-dentistry.inc1': 'تقييم للابتسامة ومناقشة النتائج الواقعية',
         'svc.cosmetic-dentistry.inc2': 'تبييض احترافي للأسنان',
         'svc.cosmetic-dentistry.inc3': 'قشور خزفية وقشور من الكومبوزيت',
         'svc.cosmetic-dentistry.inc4': 'تيجان الأسنان وحشوات بلون الأسنان',
         'svc.cosmetic-dentistry.inc5': 'إعادة تشكيل الأسنان وتلميع الحواف',
         'svc.cosmetic-dentistry.step1': 'الاستشارة: نفحص أسنانك ونناقش الخيارات معك.',
         'svc.cosmetic-dentistry.step2': 'فحص صحي للتأكد من جاهزية الأسنان واللثة.',
         'svc.cosmetic-dentistry.step3': 'نتفق على اللون والشكل اللذين تريدهما.',
         'svc.cosmetic-dentistry.step4': 'يُنفَّذ العلاج، غالبًا في زيارة أو زيارتين.',
         'svc.cosmetic-dentistry.step5': 'موعد مراجعة قصير للتأكد من رضاك عن النتيجة.',
         'svc.cosmetic-dentistry.aftercare': 'تتصبغ الأسنان المبيّضة مجددًا إذا عدت مباشرة إلى القهوة والشاي والنبيذ الأحمر والتدخين، لذلك نطلب منك تجنبها خلال أول 48 ساعة. تُنظَّف القشور والتيجان تمامًا مثل الأسنان الطبيعية: بالفرشاة مرتين يوميًا وبالخيط. وتجنّب قضم أظافرك أو فتح العبوات بأسنانك الأمامية، لأن الخزف قد يتشقق.',
         'svc.cosmetic-dentistry.fact1.label': 'مدة العلاج',
         'svc.cosmetic-dentistry.fact1.value': 'من زيارة إلى 3 زيارات',
         'svc.cosmetic-dentistry.fact2.label': 'مدة الموعد',
         'svc.cosmetic-dentistry.fact2.value': 'من 45 إلى 90 دقيقة',
